 		writer Writer
 		lock   sync.RWMutex
 	}

 	concreteWriter struct {
 		infoLog   io.WriteCloser
 		errorLog  io.WriteCloser
 		severeLog io.WriteCloser
 		slowLog   io.WriteCloser
 		statLog   io.WriteCloser
 		stackLog  io.Writer
 	}
